class Solution:
    def maxSubgraphScore(self, n: int, edges: List[List[int]], good: List[int]) -> List[int]:
        import sys
        sys.setrecursionlimit(400000)
        w = [1 if x else -1 for x in good]
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        g = w[:]
        def dfs(u, p):
            for v in adj[u]:
                if v != p:
                    dfs(v, u)
                    if g[v] > 0: g[u] += g[v]
        dfs(0, -1)
        ans = [0] * n
        up = [0] * n
        ans[0] = g[0]
        def reroot(u, p):
            for v in adj[u]:
                if v != p:
                    up[v] = max(0, g[u] + up[u] - max(0, g[v]))
                    ans[v] = g[v] + up[v]
                    reroot(v, u)
        reroot(0, -1)
        return ans

