class Solution {
    private List<List<Integer>> adj;
    private long[] g, up;
    private int[] ans;
    public int[] maxSubgraphScore(int n, int[][] edges, int[] good) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        g = new long[n]; up = new long[n]; ans = new int[n];
        for (int i = 0; i < n; i++) g[i] = good[i] == 1 ? 1 : -1;
        dfs(0, -1);
        ans[0] = (int) g[0];
        reroot(0, -1);
        return ans;
    }
    private void dfs(int u, int p) {
        for (int v : adj.get(u)) if (v != p) { dfs(v, u); if (g[v] > 0) g[u] += g[v]; }
    }
    private void reroot(int u, int p) {
        for (int v : adj.get(u)) if (v != p) {
            up[v] = Math.max(0, g[u] + up[u] - Math.max(0, g[v]));
            ans[v] = (int) (g[v] + up[v]);
            reroot(v, u);
        }
    }
}

