class Solution:
    def maxSubgraphScore(self, n: int, edges: List[List[int]], good: List[int]) -> List[int]:
        from collections import deque
        w = [1 if x else -1 for x in good]
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        par = [-1] * n
        order = []
        seen = [False] * n
        dq = deque([0]); seen[0] = True
        while dq:
            u = dq.popleft(); order.append(u)
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True; par[v] = u; dq.append(v)
        g = w[:]
        for u in reversed(order):
            p = par[u]
            if p >= 0 and g[u] > 0:
                g[p] += g[u]
        up = [0] * n
        ans = [0] * n
        for u in order:
            p = par[u]
            if p >= 0:
                up[u] = max(0, g[p] + up[p] - max(0, g[u]))
            ans[u] = g[u] + up[u]
        return ans

