class Solution {
public:
    vector<int> maxSubgraphScore(int n, vector<vector<int>>& edges, vector<int>& good) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<int> par(n, -1), order;
        vector<char> seen(n, 0);
        queue<int> dq; dq.push(0); seen[0] = 1;
        while (!dq.empty()) {
            int u = dq.front(); dq.pop(); order.push_back(u);
            for (int v : adj[u]) if (!seen[v]) { seen[v] = 1; par[v] = u; dq.push(v); }
        }
        vector<long long> g(n), up(n, 0);
        for (int i = 0; i < n; i++) g[i] = good[i] ? 1 : -1;
        for (int i = n - 1; i >= 1; i--) {
            int u = order[i], p = par[u];
            if (g[u] > 0) g[p] += g[u];
        }
        vector<int> ans(n);
        for (int u : order) {
            int p = par[u];
            if (p >= 0) up[u] = max(0LL, g[p] + up[p] - max(0LL, g[u]));
            ans[u] = (int)(g[u] + up[u]);
        }
        return ans;
    }
};

