class Solution {
    public int[] maxSubgraphScore(int n, int[][] edges, int[] good) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] par = new int[n]; Arrays.fill(par, -1);
        int[] order = new int[n];
        boolean[] seen = new boolean[n];
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(0); seen[0] = true;
        int idx = 0;
        while (!dq.isEmpty()) {
            int u = dq.poll(); order[idx++] = u;
            for (int v : adj.get(u)) if (!seen[v]) { seen[v] = true; par[v] = u; dq.add(v); }
        }
        long[] g = new long[n], up = new long[n];
        for (int i = 0; i < n; i++) g[i] = good[i] == 1 ? 1 : -1;
        for (int i = n - 1; i >= 1; i--) {
            int u = order[i], p = par[u];
            if (g[u] > 0) g[p] += g[u];
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int u = order[i], p = par[u];
            if (p >= 0) up[u] = Math.max(0, g[p] + up[p] - Math.max(0, g[u]));
            ans[u] = (int) (g[u] + up[u]);
        }
        return ans;
    }
}

